import { ADS_USDC, createAdsWallet, validatePaymentRequirements } from './ads-wallet.mjs';
export const COMPATIBILITY_AMOUNT = '50000000';
const idPattern = /^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/i;
